import{_ as v,b as l,c,d as a,t as o,C as i,u as n}from"./index-I5uTs6b4.js";const f={class:"level-page"},p={class:"level-content"},r={class:"level-title"},u={__name:"Level74",props:{id:{type:String,required:!0}},setup(t){const s=n();function d(){sessionStorage.setItem("skipIntro","1"),s.push("/")}return(_,e)=>(l(),c("div",f,[a("button",{class:"back-btn",onClick:d},"← Back to Index"),a("div",p,[a("h1",r,"SI-"+o(t.id),1),e[0]||(e[0]=i('<p class="level-name" data-v-91538fe5>&quot;逐日航迹&quot;</p><div class="section" data-v-91538fe5><h2 data-v-91538fe5>生存难度：宜居</h2><div class="difficulty" data-v-91538fe5><ul class="class-list" data-v-91538fe5><li data-v-91538fe5><span class="class-bullet safe" data-v-91538fe5></span> 安全</li><li data-v-91538fe5><span class="class-bullet stable" data-v-91538fe5></span> 稳定</li></ul></div></div><div class="section" data-v-91538fe5><h2 data-v-91538fe5>层级描述</h2><p data-v-91538fe5>Level SI-74 是一片无边无际的高空阈限空间，全域被永恒的黄昏笼罩，唯一的核心存在是一架通体银白、机身带有协和标识的飞行器，型号为协和 001 号原型机。这架飞机拆除了部分乘客座椅以安装科学仪器，并在机背开设了专用观察窗，流浪者将其命名为<strong data-v-91538fe5>逐日号</strong>。</p><p data-v-91538fe5>该层级没有地面、没有云层，只有从橘红渐变至暗紫的黄昏天幕，以及晨昏线后恒定追随的黑夜。层级内空气稀薄却可供人类正常呼吸，环境无风无云，整片空间寂静无比，唯有逐日号引擎的轰鸣持续回荡。整个层级空间呈环形闭合状态，逐日号始终沿着固定航线，朝着天空尽头那轮日蚀高速飞行，飞行速度恒定维持在 <strong data-v-91538fe5>2.04 马赫</strong>。</p><p data-v-91538fe5>层级存在固定循环规则：每次追逐月影 74 分钟后，飞机燃油便会彻底耗尽，飞行速度随之急剧下降，无法始终追上日蚀。逐日号会一次次进入日蚀的庞然巨影之中，奋力追逐，再被月影抛离；等到天幕重现天明，月影再度掠过机身时，飞机燃油会自行完全补充，机体随即重新加速，开启下一轮追逐，如此周而复始，永不停歇。</p><p data-v-91538fe5>层级内所有可活动区域仅限逐日号客机的机身内部与机翼表面，除此之外无任何可落脚、可探索的空间。</p></div><div class="section appendix" data-v-91538fe5><h2 data-v-91538fe5>附录：追逐往日之影</h2><p class="poetic" data-v-91538fe5>油量见底，速度在坠<br data-v-91538fe5>晨昏线从舷窗里追上<br data-v-91538fe5>月影不驻，往日不返<br data-v-91538fe5>尾焰滑入未来的黑</p></div><div class="section" data-v-91538fe5><h2 data-v-91538fe5>入口</h2><p data-v-91538fe5>极少数情况下，乘坐飞行器、把玩飞机模型，或是内心怀揣&quot;驻留过往&quot;强烈执念的人，会意外切入该层级。</p></div><div class="section" data-v-91538fe5><h2 data-v-91538fe5>出口</h2><p data-v-91538fe5>当逐日号引擎发出异响、机身出现剧烈颠簸时，迅速找到机舱内任意座位坐稳系好安全带，此时有 60% 概率被随机传送至其他危险层级，40% 概率进入安全层级。</p></div>',6))])]))}},b=v(u,[["__scopeId","data-v-91538fe5"]]);export{b as default};
